package com.kgsat.payment.consumer; import com.kgsat.payment.model.OrderEvent; import com.kgsat.payment.producer.PaymentProducer; import com.kgsat.payment.repository.ProcessedOrderRepository; import org.junit.jupiter.api.*; import org.springframework.kafka.support.Acknowledgment; import java.math.BigDecimal; import java.time.Instant; import static org.mockito.Mockito.*; class PaymentConsumerTest { @Test void publishesAndAcknowledgesSuccessfulPayment(){var producer=mock(PaymentProducer.class);var ack=mock(Acknowledgment.class);var consumer=new PaymentConsumer(new ProcessedOrderRepository(),producer);consumer.consume(new OrderEvent("o","c",BigDecimal.ONE,false,Instant.now()),ack);verify(producer).send(any());verify(ack).acknowledge();} }
